// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address receiver, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        receiver = address(0);
        vm.assume(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(address receiver, uint256 amount) public {
        _run(receiver, amount);
    }

    receive() external payable {}
}
